1	import { Router } from "express";
2	import { z } from "zod";
3	import type { Db } from "@paperclipai/db";
4	import { validate } from "../middleware/validate.js";
5	import { assertCompanyAccess, getActorInfo } from "./authz.js";
6	import { inboxDismissalService, logActivity } from "../services/index.js";
7	
8	const inboxDismissalSchema = z.object({
9	  itemKey: z.string().trim().min(1).regex(/^(approval|join|run):.+$/, "Unsupported inbox item key"),
10	});
11	
12	export function inboxDismissalRoutes(db: Db) {
13	  const router = Router();
14	  const svc = inboxDismissalService(db);
15	
16	  router.get("/companies/:companyId/inbox-dismissals", async (req, res) => {
17	    const companyId = req.params.companyId as string;
18	    assertCompanyAccess(req, companyId);
19	    if (req.actor.type !== "board") {
20	      res.status(403).json({ error: "Board authentication required" });
21	      return;
22	    }
23	    if (!req.actor.userId) {
24	      res.status(403).json({ error: "Board user context required" });
25	      return;
26	    }
27	    const dismissals = await svc.list(companyId, req.actor.userId);
28	    res.json(dismissals);
29	  });
30	
31	  router.post(
32	    "/companies/:companyId/inbox-dismissals",
33	    validate(inboxDismissalSchema),
34	    async (req, res) => {
35	      const companyId = req.params.companyId as string;
36	      assertCompanyAccess(req, companyId);
37	      if (req.actor.type !== "board") {
38	        res.status(403).json({ error: "Board authentication required" });
39	        return;
40	      }
41	      if (!req.actor.userId) {
42	        res.status(403).json({ error: "Board user context required" });
43	        return;
44	      }
45	
46	      const dismissal = await svc.dismiss(companyId, req.actor.userId, req.body.itemKey, new Date());
47	      const actor = getActorInfo(req);
48	      await logActivity(db, {
49	        companyId,
50	        actorType: actor.actorType,
51	        actorId: actor.actorId,
52	        agentId: actor.agentId,
53	        runId: actor.runId,
54	        action: "inbox.dismissed",
55	        entityType: "company",
56	        entityId: companyId,
57	        details: {
58	          userId: req.actor.userId,
59	          itemKey: dismissal.itemKey,
60	          dismissedAt: dismissal.dismissedAt,
61	        },
62	      });
63	
64	      res.status(201).json(dismissal);
65	    },
66	  );
67	
68	  return router;
69	}
